SELECT table_name FROM information_schema.tables WHERE table_schema = 'app' AND (table_name ILIKE '%watermark%' OR table_name ILIKE '%overlay%' OR table_name ILIKE '%render%' OR table_name ILIKE '%live%' OR table_name ILIKE '%share%' OR table_name ILIKE '%spectator%' OR table_name ILIKE '%stream%' OR table_name ILIKE '%recording%' OR table_name ILIKE '%replay%' OR table_name ILIKE '%clip%' OR table_name ILIKE '%video%' OR table_name ILIKE '%free_video%') ORDER BY table_name;
